    private final SimpleObjectPool<Set<Task>> lockListenersPool = new SimpleObjectPool<>(
            pool -> new ReferenceArraySet<>(32),
            Set::clear,
            Set::clear,
            4096
    );
    private final Object schedulingMutex = new Object();
