        }
        // 超过最大会话数量
        if (resutl == AuthResultConstant.EXCEED_SESSIONS_MAXNUM) {
            throw new ExcessiveAttemptsException();
        }
        // 没找到帐号(用户不存在)
        if (resutl == AuthResultConstant.USER_NOT_EXIST) {
            throw new UnknownAccountException();
